using mobile.Models;
using mobile.Views;
using System.Collections.ObjectModel;
using System.Windows.Input;

namespace mobile.ViewModels
{
    public class MyBooksViewModel : BaseViewModel
    {
        public ObservableCollection<Book> UserBooks { get; set; }
        public ICommand AddBookCommand { get; }

        public MyBooksViewModel()
        {
            UserBooks = new ObservableCollection<Book>
            {
                new Book { Title = "The Lord of the Rings", Author = "J.R.R. Tolkien", Description = "An epic fantasy novel about the struggle for the One Ring in Middle-earth.",
                    ImageUrl = "https://images.moviesanywhere.com/198e228b071c60f5ad57e5f62fe60029/ff22cad6-2218-414d-b853-3f95d76905c7.jpg" },
                new Book { Title = "Dune", Author = "Frank Herbert", Description = "A science fiction masterpiece about politics, religion, and power on the desert planet Arrakis.",
                    ImageUrl = "https://www.britishbook.ua/upload/resize_cache/iblock/78e/rbnu7vnptr78djk0uj9ztps3xp0jophg/1900_800_174b5ed2089e1946312e2a80dcd26f146/knyga_dune_book_1.jpg" },
                new Book { Title = "1984", Author = "George Orwell",  Description = "A dystopian novel depicting a totalitarian society under constant surveillance.",
                    ImageUrl = "https://encrypted-tbn2.gstatic.com/shopping?q=tbn:ANd9GcTDbJO_voYmlKniC7VdFvDCJ99gmjE8WARjIjEMgAH7BnnChlCJ_XxZS7OLtNn2aXJ3n3_HHblgW8QtbBllxu_5vHG0fbYGGBdpv3gcIXu4&usqp=CAc" },
                new Book { Title = "To Kill a Mockingbird", Author = "Harper Lee", Description = "A story about racial injustice and moral growth in the American South.",
                    ImageUrl = "data:image/webp;base64," }
            };

            AddBookCommand = new Command(async () => await Shell.Current.GoToAsync(nameof(AddBookPage)));
        }
    }
}
